'use client'

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type FocusEvent,
  type PointerEvent,
} from 'react'
import {
  ScrollSurfEngine,
  cardTransform,
  trackTransform,
  type ScrollSurfStep,
  type ScrollSurfTransform,
  type ScrollSurfVariant,
} from './scroll-surf.engine'

export interface ScrollSurfItem {
  id: string
  image: string
  title: string
  subtitle?: string
  href?: string
}

export interface ScrollSurfOptions {
  variant: ScrollSurfVariant
  perspective: number
  depth: number
  spread: number
  rise: number
  tilt: number
  cardWidth: number
  scrollPerItem: number
  scrollLength: number
  smoothing: number
  showTitles: boolean
  heading: string
  subheading: string
  hint: string
  background: string
  viewportHeight: string
}

export interface ScrollSurfProps extends Partial<ScrollSurfOptions> {
  items: ScrollSurfItem[]
  className?: string
  style?: CSSProperties
}

export const scrollSurfDefaults: ScrollSurfOptions = {
  variant: 'magnetic',
  perspective: 2000,
  depth: 288,
  spread: 240,
  rise: 84,
  tilt: -50,
  cardWidth: 300,
  scrollPerItem: 600,
  scrollLength: 50000,
  smoothing: 0.08,
  showTitles: true,
  heading: 'Field Journal',
  subheading: 'Archive 2026',
  hint: 'Scroll to surf',
  background: '#000000',
  viewportHeight: '100dvh',
}

const MAX_DT = 1 / 30
const AHEAD = 14
const CARD_ASPECT = 4 / 3
const HOVER_EASE = 'cubic-bezier(0.4, 0, 0.2, 1)'
const MOTION_QUERY = '(prefers-reduced-motion: reduce)'

function subscribeMotion(onChange: () => void) {
  const list = window.matchMedia(MOTION_QUERY)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

function useReducedMotion() {
  return useSyncExternalStore(
    subscribeMotion,
    () => window.matchMedia(MOTION_QUERY).matches,
    () => false,
  )
}

function scrollParentOf(node: HTMLElement): HTMLElement | Window {
  let el = node.parentElement
  while (el) {
    const { overflowY } = getComputedStyle(el)
    if ((overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight) {
      return el
    }
    el = el.parentElement
  }
  return window
}

function translate({ x, y, z }: ScrollSurfTransform) {
  return `translate3d(${x}px, ${y}px, ${z}px)`
}

export function ScrollSurf({
  items,
  variant = scrollSurfDefaults.variant,
  perspective = scrollSurfDefaults.perspective,
  depth = scrollSurfDefaults.depth,
  spread = scrollSurfDefaults.spread,
  rise = scrollSurfDefaults.rise,
  tilt = scrollSurfDefaults.tilt,
  cardWidth = scrollSurfDefaults.cardWidth,
  scrollPerItem = scrollSurfDefaults.scrollPerItem,
  scrollLength = scrollSurfDefaults.scrollLength,
  smoothing = scrollSurfDefaults.smoothing,
  showTitles = scrollSurfDefaults.showTitles,
  heading = scrollSurfDefaults.heading,
  subheading = scrollSurfDefaults.subheading,
  hint = scrollSurfDefaults.hint,
  background = scrollSurfDefaults.background,
  viewportHeight = scrollSurfDefaults.viewportHeight,
  className,
  style,
}: ScrollSurfProps) {
  const count = items.length
  // Enough copies that the track never runs out ahead
  const copies = count ? Math.ceil(AHEAD / count) + 1 : 1
  const reduced = useReducedMotion()
  const hoverEnabled = variant !== 'simple' && !reduced
  const step: ScrollSurfStep = { x: spread, y: -rise, z: -depth }
  const engineRef = useRef<ScrollSurfEngine | null>(null)
  if (!engineRef.current) {
    engineRef.current = new ScrollSurfEngine({
      count,
      copies,
      scrollPerItem,
      step,
      variant,
      smoothing,
      instant: false,
    })
  }
  const engine = engineRef.current
  const [active, setActive] = useState(0)
  const [hovered, setHovered] = useState<number | null>(null)
  const rootRef = useRef<HTMLDivElement>(null)
  const trackRef = useRef<HTMLDivElement>(null)
  const cardRefs = useRef<(HTMLElement | null)[]>([])
  const paintedHoverRef = useRef(false)
  const wakeRef = useRef<() => void>(() => {})
  const wake = useCallback(() => wakeRef.current(), [])

  const cardCss = (index: number) => {
    const { x, y, z } = cardTransform(index, engine.step)
    const { scale, lift } = engine.cardState(index)
    return `translate3d(${x}px, ${y + lift}px, ${z}px) rotateY(${tilt}deg) scale(${scale})`
  }

  const paint = () => {
    const track = trackRef.current
    if (track) track.style.transform = translate(engine.trackTransform())
    if (engine.hoverActive || paintedHoverRef.current) {
      cardRefs.current.forEach((el, index) => {
        if (el) el.style.transform = cardCss(index)
      })
    }
    paintedHoverRef.current = engine.hoverActive
    setActive(engine.activeIndex)
  }
  const paintRef = useRef(paint)
  useEffect(() => {
    paintRef.current = paint
  })

  useEffect(() => {
    engine.setOptions({
      count,
      copies,
      scrollPerItem,
      step: { x: spread, y: -rise, z: -depth },
      variant: hoverEnabled ? variant : 'simple',
      smoothing,
      instant: reduced,
    })
    wake()
  }, [
    engine,
    wake,
    count,
    copies,
    scrollPerItem,
    spread,
    rise,
    depth,
    variant,
    hoverEnabled,
    smoothing,
    reduced,
  ])

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    let visible = true
    let frame = 0
    let last = 0
    let first = true

    const measureCenters = () => {
      cardRefs.current.forEach((el, index) => {
        if (!el) return
        const rect = el.getBoundingClientRect()
        engine.setCardCenter(index, rect.left + rect.width / 2, rect.top + rect.height / 2)
      })
    }

    const loop = (now: number) => {
      frame = 0
      if (!visible) return
      const dt = last ? Math.min((now - last) / 1000, MAX_DT) : 1 / 60
      last = now
      if (engine.pointer) measureCenters()
      engine.tick(dt)
      paintRef.current()
      if (!engine.idle) frame = requestAnimationFrame(loop)
      else last = 0
    }

    const start = () => {
      if (frame || !visible) return
      last = 0
      frame = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (frame) cancelAnimationFrame(frame)
      frame = 0
      last = 0
    }

    const measure = () => {
      engine.setTarget(-root.getBoundingClientRect().top, first)
      first = false
      start()
    }

    wakeRef.current = start
    measure()

    window.addEventListener('scroll', measure, { passive: true, capture: true })
    const resize = new ResizeObserver(measure)
    resize.observe(root)

    const intersection = new IntersectionObserver(([entry]) => {
      visible = entry?.isIntersecting ?? true
      if (visible) measure()
      else stop()
    })
    intersection.observe(root)

    const onVisibility = () => {
      if (document.hidden) stop()
      else start()
    }
    document.addEventListener('visibilitychange', onVisibility)

    return () => {
      stop()
      window.removeEventListener('scroll', measure, { capture: true })
      resize.disconnect()
      intersection.disconnect()
      document.removeEventListener('visibilitychange', onVisibility)
      wakeRef.current = () => {}
    }
  }, [engine])

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (!hoverEnabled || e.pointerType !== 'mouse') return
    engine.setPointer(e.clientX, e.clientY)
    wake()
  }

  const onPointerLeave = () => {
    engine.setPointer(0, null)
    wake()
  }

  const onCardFocus = (e: FocusEvent<HTMLElement>, index: number) => {
    const root = rootRef.current
    if (!root || !count || !e.currentTarget.matches(':focus-visible')) return
    const current = -root.getBoundingClientRect().top
    const loop = count * scrollPerItem
    const ahead = (((index * scrollPerItem - current) % loop) + loop) % loop
    const back = ahead - loop
    const top = ahead > loop / 2 && current + back >= 0 ? back : ahead
    scrollParentOf(root).scrollBy({ top, behavior: reduced ? 'auto' : 'smooth' })
  }

  const activeItem = items[active]
  const cardHeight = Math.round(cardWidth * CARD_ASPECT)
  const fade = reduced ? 0 : 300
  const cards = Array.from({ length: count * copies }, (_, index) => {
    const item = items[index % count]
    const copy = Math.floor(index / count)
    if (!item) return null
    const cardStyle: CSSProperties = {
      width: cardWidth,
      height: cardHeight,
      transform: cardCss(index),
      transformStyle: 'preserve-3d',
      boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
    }
    const shared = {
      style: cardStyle,
      ref: (el: HTMLElement | null) => {
        cardRefs.current[index] = el
      },
      tabIndex: copy === 0 ? 0 : -1,
      'aria-hidden': copy > 0 ? true : undefined,
      'aria-current': copy === 0 && index === active ? ('true' as const) : undefined,
      onPointerEnter: () => setHovered(index),
      onPointerLeave: () => setHovered((h) => (h === index ? null : h)),
      onFocus: (e: FocusEvent<HTMLElement>) => onCardFocus(e, index % count),
    }
    const content = (
      <>
        <span
          className="uig-scroll-surf__frame block h-full w-full"
          style={{
            filter: `brightness(${hovered === index ? 1 : 0.75})`,
            transition: `filter ${fade}ms ${HOVER_EASE}`,
          }}
        >
          <img
            src={item.image}
            alt={item.title}
            draggable={false}
            className="uig-scroll-surf__image block h-full w-full object-cover"
          />
        </span>
        <span
          aria-hidden="true"
          className="uig-scroll-surf__shade pointer-events-none absolute inset-0"
          style={{
            backgroundImage: 'linear-gradient(to top right, rgba(0, 0, 0, 0.2), transparent)',
          }}
        />
      </>
    )
    return item.href ? (
      <a
        key={`${item.id}-${copy}`}
        href={item.href}
        className="uig-scroll-surf__card absolute overflow-hidden bg-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-current"
        {...shared}
      >
        {content}
      </a>
    ) : (
      <div
        key={`${item.id}-${copy}`}
        className="uig-scroll-surf__card absolute overflow-hidden bg-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-current"
        {...shared}
      >
        {content}
      </div>
    )
  })

  return (
    <div
      ref={rootRef}
      className={['uig-scroll-surf', 'relative w-full', className].filter(Boolean).join(' ')}
      style={{ height: scrollLength, ...style }}
    >
      <div
        className="uig-scroll-surf__viewport sticky top-0 w-full overflow-clip text-white"
        style={{ height: viewportHeight, background }}
        onPointerMove={onPointerMove}
        onPointerLeave={onPointerLeave}
      >
        {showTitles && (
          <div
            className="uig-scroll-surf__heading pointer-events-none absolute z-50 mix-blend-difference"
            style={{ top: '3cqw', left: '3cqw' }}
          >
            {heading && (
              <p
                className="uig-scroll-surf__title font-bold leading-[0.9] tracking-tighter uppercase"
                style={{ fontSize: 'clamp(2rem, 6cqw, 5rem)', marginLeft: '4cqw' }}
              >
                {heading}
              </p>
            )}
            {subheading && (
              <p
                className="uig-scroll-surf__title font-bold leading-[0.9] tracking-tighter uppercase"
                style={{ fontSize: 'clamp(2rem, 6cqw, 5rem)' }}
              >
                {subheading}
                <span className="uig-scroll-surf__count relative top-[0.6em] ml-2 align-top font-mono text-[0.4em] tabular-nums">
                  ({count})
                </span>
              </p>
            )}
          </div>
        )}
        {showTitles && hint && (
          <div
            className="uig-scroll-surf__hint pointer-events-none absolute z-50 font-mono text-xs tracking-wider uppercase opacity-70"
            style={{ bottom: '3cqw', right: '3cqw' }}
          >
            {hint}
          </div>
        )}
        <div
          className="uig-scroll-surf__scene absolute inset-0 flex items-center justify-center"
          style={{ perspective, perspectiveOrigin: '10% 10%' }}
        >
          <div
            ref={trackRef}
            className="uig-scroll-surf__track relative h-0 w-0"
            style={{
              transformStyle: 'preserve-3d',
              transform: translate(trackTransform(engine.progress, step)),
            }}
          >
            {cards}
          </div>
        </div>
      </div>
      <div className="uig-scroll-surf__live sr-only" aria-live="polite">
        {activeItem?.title}
        {activeItem?.subtitle ? `, ${activeItem.subtitle}` : ''}
      </div>
    </div>
  )
}

export type ScrollSurfVariant = 'magnetic' | 'uplift' | 'simple'

export interface ScrollSurfStep {
  x: number
  y: number
  z: number
}

export interface ScrollSurfEngineOptions {
  count: number
  copies: number
  scrollPerItem: number
  step: ScrollSurfStep
  variant: ScrollSurfVariant
  smoothing: number
  instant: boolean
}

export interface ScrollSurfTransform {
  x: number
  y: number
  z: number
}

export interface ScrollSurfCardState {
  scale: number
  lift: number
}

export interface SpringConfig {
  mass: number
  stiffness: number
  damping: number
}

export interface Spring {
  value: number
  velocity: number
}

interface Card {
  scale: Spring
  lift: Spring
  cx: number
  cy: number
}

export const hoverSpring: SpringConfig = { mass: 0.5, stiffness: 300, damping: 20 }
export const HOVER_REACH = 400
export const MAGNET_SCALE = 0.5
export const LIFT_PX = 100

const SCROLL_SETTLE = 0.01
const SCALE_SETTLE = 0.0005
const LIFT_SETTLE = 0.05

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max)
}

// Track offset that puts card `progress` at the front
export function trackTransform(progress: number, step: ScrollSurfStep) {
  return { x: -progress * step.x, y: -progress * step.y, z: -progress * step.z }
}

export function cardTransform(index: number, step: ScrollSurfStep) {
  return { x: index * step.x, y: index * step.y, z: index * step.z }
}

// Card position relative to the camera, in scene pixels
export function surferTransform(
  progress: number,
  index: number,
  step: ScrollSurfStep,
): ScrollSurfTransform {
  const distance = index - progress
  return { x: distance * step.x, y: distance * step.y, z: distance * step.z }
}

// Exact damped spring solution, stable for any dt
export function stepSpring(spring: Spring, target: number, dt: number, config: SpringConfig) {
  const { mass, stiffness, damping } = config
  const w0 = Math.sqrt(stiffness / mass)
  const zeta = damping / (2 * Math.sqrt(stiffness * mass))
  const d = spring.value - target
  const v = spring.velocity
  if (zeta < 1) {
    const wd = w0 * Math.sqrt(1 - zeta * zeta)
    const decay = Math.exp(-zeta * w0 * dt)
    const cos = Math.cos(wd * dt)
    const sin = Math.sin(wd * dt)
    const b = (v + zeta * w0 * d) / wd
    spring.value = target + decay * (d * cos + b * sin)
    spring.velocity = decay * ((b * wd - zeta * w0 * d) * cos - (d * wd + zeta * w0 * b) * sin)
    return
  }
  if (zeta === 1) {
    const decay = Math.exp(-w0 * dt)
    const b = v + w0 * d
    spring.value = target + decay * (d + b * dt)
    spring.velocity = decay * (b - w0 * (d + b * dt))
    return
  }
  const r = w0 * Math.sqrt(zeta * zeta - 1)
  const s1 = -zeta * w0 + r
  const s2 = -zeta * w0 - r
  const a = (v - s2 * d) / (s1 - s2)
  const b = d - a
  const e1 = Math.exp(s1 * dt)
  const e2 = Math.exp(s2 * dt)
  spring.value = target + a * e1 + b * e2
  spring.velocity = a * s1 * e1 + b * s2 * e2
}

function settle(spring: Spring, target: number, threshold: number) {
  if (Math.abs(spring.value - target) > threshold || Math.abs(spring.velocity) > threshold * 60) {
    return false
  }
  spring.value = target
  spring.velocity = 0
  return true
}

export class ScrollSurfEngine {
  target = 0
  current = 0
  idle = true
  hoverActive = false
  pointer: { x: number; y: number } | null = null
  count: number
  copies: number
  scrollPerItem: number
  step: ScrollSurfStep
  variant: ScrollSurfVariant
  smoothing: number
  instant: boolean
  private cards: Card[] = []

  constructor(options: ScrollSurfEngineOptions) {
    this.count = options.count
    this.copies = options.copies
    this.scrollPerItem = options.scrollPerItem
    this.step = options.step
    this.variant = options.variant
    this.smoothing = options.smoothing
    this.instant = options.instant
    this.allocate()
  }

  get cardCount() {
    return this.count * this.copies
  }

  get loop() {
    return this.count * this.scrollPerItem
  }

  // Scroll position in items, wrapped to one set
  get progress() {
    const loop = this.loop
    if (loop <= 0) return 0
    const px = ((this.current % loop) + loop) % loop
    return px / this.scrollPerItem
  }

  get activeIndex() {
    return this.count ? Math.round(this.progress) % this.count : 0
  }

  setOptions(next: Partial<ScrollSurfEngineOptions>) {
    if (next.count !== undefined) this.count = next.count
    if (next.copies !== undefined) this.copies = next.copies
    if (next.scrollPerItem !== undefined) this.scrollPerItem = next.scrollPerItem
    if (next.step !== undefined) this.step = next.step
    if (next.variant !== undefined) this.variant = next.variant
    if (next.smoothing !== undefined) this.smoothing = next.smoothing
    if (next.instant !== undefined) this.instant = next.instant
    if (this.cards.length !== this.cardCount) this.allocate()
    this.idle = false
  }

  setTarget(px: number, jump = false) {
    this.target = Math.max(0, px)
    if (jump || this.instant) this.current = this.target
    this.idle = false
  }

  setPointer(x: number, y: number | null) {
    this.pointer = y === null ? null : { x, y }
    this.idle = false
  }

  setCardCenter(index: number, x: number, y: number) {
    const card = this.cards[index]
    if (!card) return
    card.cx = x
    card.cy = y
  }

  trackTransform() {
    return trackTransform(this.progress, this.step)
  }

  cardTransform(index: number) {
    return cardTransform(index, this.step)
  }

  cardState(index: number): ScrollSurfCardState {
    const card = this.cards[index]
    return card ? { scale: card.scale.value, lift: card.lift.value } : { scale: 1, lift: 0 }
  }

  tick(dt: number) {
    const diff = this.target - this.current
    if (Math.abs(diff) < SCROLL_SETTLE || this.instant) this.current = this.target
    else {
      // Frame-rate independent lerp, same feel as smoothing at 60fps
      const rate = 1 - Math.pow(1 - clamp(this.smoothing, 0.01, 1), dt * 60)
      this.current += diff * rate
    }
    let settled = this.current === this.target
    let active = false
    for (const card of this.cards) {
      const near = 1 - clamp(this.distance(card) / HOVER_REACH, 0, 1)
      const scale = this.variant === 'magnetic' ? 1 + MAGNET_SCALE * near : 1
      const lift = this.variant === 'uplift' ? -LIFT_PX * near : 0
      if (this.instant) {
        card.scale.value = scale
        card.lift.value = lift
      } else {
        stepSpring(card.scale, scale, dt, hoverSpring)
        stepSpring(card.lift, lift, dt, hoverSpring)
        if (!settle(card.scale, scale, SCALE_SETTLE)) settled = false
        if (!settle(card.lift, lift, LIFT_SETTLE)) settled = false
      }
      if (card.scale.value !== 1 || card.lift.value !== 0) active = true
    }
    this.hoverActive = active
    this.idle = settled
  }

  private distance(card: Card) {
    if (!this.pointer || this.variant === 'simple') return Infinity
    return Math.hypot(this.pointer.x - card.cx, this.pointer.y - card.cy)
  }

  private allocate() {
    this.cards = Array.from({ length: this.cardCount }, () => ({
      scale: { value: 1, velocity: 0 },
      lift: { value: 0, velocity: 0 },
      cx: 0,
      cy: 0,
    }))
    this.hoverActive = false
  }
}
